async function cb(req){const raw=await req.text();if(raw.length>24000)cf('Request too large.',413);try{return JSON.parse(raw);}catch{cf('Invalid request.');}}
async function digest(s){return new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)));}
async function keyMatches(a,b){const [x,y]=await Promise.all([digest(a),digest(b)]);let diff=0;for(let i=0;i<x.length;i++)diff|=x[i]^y[i];return diff===0;}
